const tipoTramite = partes[2] || "Trámite de Extranjería";

// Datos del remitente en WhatsApp
const remoteJid = data.key?.remoteJid || "";
const nombreCliente = data.pushName || "Cliente WhatsApp";

return {
  accion: "crear",
  nombre_cliente: nombreCliente,
  tipo_tramite: tipoTramite,
