  remoteJid: remoteJid
};

// Extraer los datos de la entrada anterior (Evolution API)
const item = $input.item.json;
const base64Data = item.base64 || item.data || ""; 
const mimeType = item.mimetype || "application/pdf"; 
const fileName = item.fileName || "documento_extranjeria.pdf";

// Limpiar el prefijo de data URI si lo tuviera
const base64Clean = base64Data.replace(/^data:.*;base64,/, "");

// Usar global.Buffer para evitar el error de TypeScript en n8n
const binaryData = global.Buffer.from(base64Clean, 'base64');

return {
  json: { 
    fileName, 
    mimeType,
    success: true 
  },
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: mimeType,
      fileName: fileName,
    }
  }
};

